function addInquiry(id) 
{
    if(!navigator.cookieEnabled) {
        $('#moduleCookie, .moduleMask').addClass('show');
        return false;
    }

    $.ajax({
        url:'https://www.super-flower.com.tw/inquiry/act/',
        type:"post",
        data:{'index_id':id,'act':5},
        cache:false,
        dataType:"text",
        success:function(result){
            var result = JSON.parse(result);
            if (result.status == 'error')
            {
                alert(result.msg.data_msg);
            }
            else if(result.status == 'add')
            {
                // $('#pr_btn_'+id).text('REMOVE FROM INQUIRY').addClass('bgSecond');
                $('#pr_btn_'+id).addClass('current');

                                    toasts.show('Added to inquiry', 'success');
                            }
            else if(result.status == 'remove')
            {
                // $('#pr_btn_'+id).text('ADD TO INQUIRY').removeClass('bgSecond');
                $('#pr_btn_'+id).removeClass('current');

                                    toasts.show('Removed', 'dark');

            }

            $('#car_list_html').html('');
            if(result.items !== null) 
            {
                printInquiryList(result.items);
                pdInquiryLen(result.items.length);
            }
        }
    });
}

